 const row=(await client.query('SELECT to_jsonb(a) AS a,to_jsonb(r) AS r,to_jsonb(o) AS o FROM crest.quote_acceptances a JOIN crest.quote_revisions r ON r.business_id=a.business_id AND r.id=a.revision_id JOIN crest_private.operations o ON o.business_id=a.business_id AND o.operation_id=a.operation_id WHERE a.business_id=$1',[legacy.business])).rows[0];
 const valid=(a,r,o)=>scalar('SELECT crest_private.quote_acceptance_kind_valid(jsonb_populate_record(null::crest.quote_acceptances,$1::jsonb),jsonb_populate_record(null::crest.quote_revisions,$2::jsonb),jsonb_populate_record(null::crest_private.operations,$3::jsonb)) AS value',[a,r,o]);assert.equal(await valid(row.a,row.r,row.o),true);
