 // Pure provenance shape only: no genuine amendment command/commit is claimed.
 assert.equal(await valid(amendment.a,amendment.r,amendment.o),true);
 for(const [a,r,o]of [[amendment.a,row.r,amendment.o],[row.a,amendment.r,row.o],[amendment.a,amendment.r,row.o],[amendment.a,{...amendment.r,parent_agreement_id:null},amendment.o],[{...amendment.a,conversion_id:randomUUID()},amendment.r,amendment.o],[row.a,row.r,{...row.o,state:'pending'}],[row.a,row.r,{...row.o,schema_version:2}],[row.a,row.r,{...row.o,result:{...row.o.result,schemaVersion:2}}],[row.a,{...row.r,state:'Sent'},row.o],[row.a,{...row.r,content_hash:'f'.repeat(64)},row.o],[row.a,{...row.r,business_id:randomUUID()},row.o],[row.a,row.r,{...row.o,actor_id:randomUUID()}],[null,row.r,row.o],[row.a,null,row.o],[row.a,row.r,null]])assert.equal(await valid(a,r,o),false);
