test('a genuine restricted initial acceptance cannot be relabelled as an amendment or unknown kind',async()=>{
 const f=await accepted();
 for(const [expression,refusal]of [["'amendment'",error=>error.code==='23514'&&error.message==='CREST_QUOTE_ACCEPTANCE_KIND_REQUIRED'],["'unknown'",error=>error.code==='23514'&&error.constraint==='quote_acceptances_kind_check'],['NULL',error=>error.code==='23502'&&error.table==='quote_acceptances'&&error.column==='kind']]){
  const before=await scalar('SELECT count(*)::int AS value FROM crest.quote_acceptances WHERE business_id=$1',[f.business]),agreements=await scalar('SELECT count(*)::int AS value FROM crest.agreements WHERE business_id=$1',[f.business]);
  await client.query("CREATE FUNCTION crest_private.test_acceptance_kind_fault() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ BEGIN NEW.kind:="+expression+";RETURN NEW;END $$;CREATE TRIGGER test_acceptance_kind_fault BEFORE INSERT ON crest.quote_acceptances FOR EACH ROW EXECUTE FUNCTION crest_private.test_acceptance_kind_fault()");
  try{await assert.rejects(accepted(f),refusal);}
  finally{await client.query('DROP TRIGGER test_acceptance_kind_fault ON crest.quote_acceptances;DROP FUNCTION crest_private.test_acceptance_kind_fault()');}
  assert.equal(await scalar('SELECT count(*)::int AS value FROM crest.quote_acceptances WHERE business_id=$1',[f.business]),before);assert.equal(await scalar('SELECT count(*)::int AS value FROM crest.agreements WHERE business_id=$1',[f.business]),agreements);assert.equal(await scalar("SELECT count(*)::int AS value FROM crest_private.operations WHERE business_id=$1 AND command_type='quote.confirmation.accept' AND state<>'committed'",[f.business]),0);
 }
 const subsequent=await accepted(f);assert.equal(await scalar("SELECT kind AS value FROM crest.quote_acceptances WHERE business_id=$1 AND id=(SELECT acceptance_id FROM crest.agreements WHERE id=$2)",[f.business,subsequent.agreementId]),'initial');
});

