async function attemptBinding(version,expectedCode,expectedMessage,state='active',sourceIndex=0){
 // Explicit fault injection in this disposable fixture only. A real restricted
 // book_job command establishes its own authority, pending operation, audits
 // and result. No existing trigger/RLS is disabled, and no operation is faked.
 const fresh=await accepted(),source=fresh.sources[typeof sourceIndex==='function'?sourceIndex(fresh):sourceIndex],targetVersion=typeof version==='function'?version(fresh):version,request=confirmedBookingRequest(fresh);assert([fresh.business,source.id,targetVersion].every(id=>/^[a-f0-9-]{36}$/.test(id)));assert(['active','withdrawn','unknown',null].includes(state));assert.equal(await scalar("SELECT to_regprocedure('crest_private.test_inject_amendment_allocation_binding()')::text AS value"),null);
 await client.query("CREATE FUNCTION crest_private.test_inject_amendment_allocation_binding() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $inject$BEGIN NEW.entitlement_version_id:=TG_ARGV[0]::uuid;NEW.authorization_state:=nullif(TG_ARGV[1],'');RETURN NEW;END$inject$");
 try{
  await client.query('REVOKE ALL ON FUNCTION crest_private.test_inject_amendment_allocation_binding() FROM PUBLIC');
  await client.query("CREATE TRIGGER z_test_amendment_allocation_binding BEFORE INSERT ON crest.allocation_plan_versions FOR EACH ROW WHEN(NEW.business_id='"+fresh.business+"'::uuid AND NEW.source_allocation_id='"+source.id+"'::uuid) EXECUTE FUNCTION crest_private.test_inject_amendment_allocation_binding('"+targetVersion+"','"+(state??'')+"')");
  await assert.rejects(book(fresh,request),error=>error.code===expectedCode&&(!expectedMessage||error.message===expectedMessage));
  assert.equal(await scalar('SELECT count(*)::int AS value FROM crest.jobs WHERE business_id=$1',[fresh.business]),0);assert.equal(await scalar('SELECT count(*)::int AS value FROM crest.allocation_plan_versions WHERE business_id=$1',[fresh.business]),0);assert.equal(await scalar('SELECT count(*)::int AS value FROM crest_private.operations WHERE business_id=$1 AND operation_id=$2',[fresh.business,request.operationId]),0);
 }finally{await client.query('DROP TRIGGER IF EXISTS z_test_amendment_allocation_binding ON crest.allocation_plan_versions');await client.query('DROP FUNCTION crest_private.test_inject_amendment_allocation_binding()');}
}
