 const original=parseOriginalOperationReference({schemaVersion:1,businessId:f.business,commandType:'operations.job.cancel',reference:{operationId:cancellation.operationId,recoveryEpoch:f.epoch,jobId:q.jobId,expectedJobVersion:cancellation.expectedJobVersion}}),found=(await web.query('SELECT crest_commands.lookup_scheduling_original($1,$2,$3,$4,$5,$6,$7,$8,$9) AS value',[...f.auth(),original])).rows[0].value;assert.deepEqual(parseSchedulingOriginalResult(found,original),cancelled);assert.deepEqual(await resolution(f,original),{schemaVersion:1,state:'original_recorded',original});
