 const original=parseOriginalOperationReference({schemaVersion:1,businessId:f.business,commandType:'operations.job.book',reference:{operationId:q.operationId,recoveryEpoch:f.epoch,jobId:q.jobId,expectedModeSequence:q.expectedModeSequence}}),found=(await web.query('SELECT crest_commands.lookup_scheduling_original($1,$2,$3,$4,$5,$6,$7,$8,$9) AS value',[...f.auth(),original])).rows[0].value;assert.deepEqual(parseSchedulingOriginalResult(found,original),saved);assert.deepEqual(await resolution(f,original),{schemaVersion:1,state:'original_recorded',original});assert.deepEqual((await web.query('SELECT crest_commands.lookup_booked_job_operation($1,$2,$3,$4,$5,$6,$7,$8,$9) AS value',[...f.auth(),q.operationId])).rows[0].value,saved);
 const oldJob=await scalar('SELECT id AS value FROM crest.jobs WHERE business_id=$1 AND id<>$2',[f.business,q.jobId]),cancelRequest=await amendedCancellation(f,oldJob),newVisitBefore=await scalar('SELECT to_jsonb(j)::text AS value FROM crest.jobs j WHERE business_id=$1 AND id=$2',[f.business,q.jobId]);assert.equal((await cancelAmended(f,cancelRequest)).state,'committed');assert.equal(await scalar('SELECT to_jsonb(j)::text AS value FROM crest.jobs j WHERE business_id=$1 AND id=$2',[f.business,q.jobId]),newVisitBefore);assert.deepEqual((await web.query('SELECT crest_commands.lookup_booked_job_operation($1,$2,$3,$4,$5,$6,$7,$8,$9) AS value',[...f.auth(),q.operationId])).rows[0].value,saved);
