 for(const role of ['crest_schema_owner','crest_quote_owner','crest_booking_owner']){await client.query('ALTER DEFAULT PRIVILEGES FOR ROLE '+role+' GRANT EXECUTE ON FUNCTIONS TO PUBLIC');try{await assert.rejects(transaction(client,()=>client.query(sql)),e=>e.code==='42501'&&e.message==='CREST_ACCEPTED_AMENDMENT_SOURCE_REVIEW_REQUIRED');}finally{await client.query('ALTER DEFAULT PRIVILEGES FOR ROLE '+role+' REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC');}}
 await transaction(client,()=>client.query(sql));assert.equal(await scalar('SELECT count(*)::int AS value FROM supabase_migrations.schema_migrations'),52);for(const role of ['crest_web','crest_export']){const expected=role==='crest_export',rights=(await client.query("SELECT has_function_privilege($1,oid,'EXECUTE') AS allowed FROM pg_proc WHERE pronamespace='crest_commands'::regnamespace AND proname IN('quote_amendment_accepted_source_context','quote_amendment_accepted_source_acceptances','quote_amendment_accepted_source_plans')",[role])).rows;assert.equal(rights.length,3);assert(rights.every(r=>r.allowed===expected));}assert.equal(await scalar("SELECT bool_or(has_schema_privilege(r,n,'CREATE')) AS value FROM unnest(ARRAY['crest_quote_owner','crest_booking_owner','crest_export']) r CROSS JOIN unnest(ARRAY['crest','crest_private','crest_commands']) n"),false);
