 for(const limit of [0,21])await assert.rejects(acceptedRead(async()=>{const context=(await acceptedSourceExporter.query('SELECT crest_commands.quote_amendment_accepted_source_context($1) AS value',[legacy.business])).rows[0].value;await acceptedSourceExporter.query('SELECT crest_commands.quote_amendment_accepted_source_acceptances($1,$2,NULL,$3)',[legacy.business,context.snapshotToken,limit]);}),e=>e.code==='22023');await assert.rejects(acceptedRead(()=>acceptedSourceExporter.query('SELECT crest_commands.quote_amendment_accepted_source_acceptances($1,$2,NULL,2)',[legacy.business,'f'.repeat(64)])),e=>e.code==='22023');
