test('accepted-source exports all retained initial, cancellation, reopening and booking graphs without filtering or changing original source',async()=>{
 const businesses=(await client.query("SELECT DISTINCT business_id FROM crest.quote_revisions WHERE kind='amendment' UNION SELECT $1::uuid ORDER BY business_id",[legacy.business])).rows.map(r=>r.business_id);assert(businesses.length>5);
 for(const business of businesses){const before=await sources(business),capture=await acceptedRead(()=>collectAcceptedAmendmentSources(acceptedSourceExporter,business,3));let bundle;try{bundle=formatAcceptedQuoteAmendmentSourceCsv(capture);}catch(error){await writeFile('.local/accepted-source-native-failure.json',JSON.stringify(capture));console.log('SYNTHETIC_ACCEPTED_SOURCE_FORMAT_FAILURE '+JSON.stringify({business,agreements:capture.rows.agreements.length,acceptances:capture.rows.acceptances.length,revisions:capture.quotes.revisions.length,plans:capture.bookings.rows.allocation_plan_versions.length}));throw error;}const specs=acceptedSourceTables(bundle);assert.equal(specs.length,24);verifyAcceptedSourceParts(bundle);for(const spec of specs){const quoteKey={quote_families:'families',quote_revisions:'revisions',quote_items:'items',condition_assessments:'assessments',quote_approvals:'approvals'}[spec.entity],commercialKey={quote_family_commercial_state:'commercialState',quote_sends:'sends',quote_acceptances:'acceptances',agreements:'agreements',scope_entitlements:'entitlements',entitlement_versions:'entitlementVersions',scope_allocations:'allocations'}[spec.entity],original=quoteKey?capture.quotes[quoteKey]:commercialKey?capture.rows[commercialKey]:capture.bookings.rows[spec.entity];assert.deepEqual(decodeAcceptedSourceTable(spec),[...original].sort((a,b)=>a.id<b.id?-1:a.id>b.id?1:0),spec.entity);}assert.equal(JSON.parse(bundle.manifest).completeBackup,false);assert.equal(JSON.parse(bundle.manifest).completeCrestExport,false);assert.throws(()=>formatQuoteAmendmentSourceCsv(capture),/QUOTE_AMENDMENT_SOURCE_CSV_REVIEW_REQUIRED/);assert.deepEqual(await sources(business),before);acceptedSourceCaptures.push({capture,bundle});}
 assert(acceptedSourceCaptures.some(s=>s.capture.rows.agreements.length>=5));assert(acceptedSourceCaptures.some(s=>s.capture.rows.acceptances.some(a=>a.kind==='amendment')));assert(acceptedSourceCaptures.some(s=>s.capture.bookings.rows.jobs.some(j=>j.state==='cancelled')));assert(acceptedSourceCaptures.some(s=>s.capture.rows.agreements.some(g=>BigInt(g.signed_delta_cents)<0n)));await writeFile('.local/accepted-source-native-summary.json',JSON.stringify({businesses:acceptedSourceCaptures.length,tables:24,maxAgreementChain:Math.max(...acceptedSourceCaptures.map(s=>s.capture.rows.agreements.length)),sourceUnchanged:true}));
});
for(const fault of ['omit-withdrawn-root','omit-plan-part','change-parent','substitute-confirmation','omit-historical-reason'])test('accepted-source refuses '+fault+' while retaining truthful counts',()=>{
 const sample=acceptedSourceCaptures.find(s=>s.capture.rows.agreements.length>=5);assert(sample);const c=structuredClone(sample.capture);
 if(fault==='omit-withdrawn-root'){c.rows.entitlements.splice(0,1);c.expectedCounts.entitlements=String(c.rows.entitlements.length);}if(fault==='omit-plan-part'){assert(c.bookings.rows.allocation_plan_parts.length>0);c.bookings.rows.allocation_plan_parts.pop();c.bookings.expectedCounts.allocation_plan_parts=String(c.bookings.rows.allocation_plan_parts.length);}if(fault==='change-parent')c.rows.agreements.find(g=>g.parent_agreement_id!==null).parent_agreement_id=c.rows.agreements.find(g=>g.version_no==='5').id;if(fault==='substitute-confirmation')c.rows.acceptances.find(a=>a.kind==='amendment').request.body.evidenceNote='Synthetic substituted evidence';if(fault==='omit-historical-reason'){const r=c.quotes.revisions.find(r=>r.customer_safe_snapshot.schemaVersion===3);delete r.customer_safe_snapshot.cancellationReason;}assert.throws(()=>formatAcceptedQuoteAmendmentSourceCsv(c),/QUOTE_AMENDMENT_SOURCE_CSV_REVIEW_REQUIRED/);
});
