test('accepted-source keeps its held snapshot through a concurrent new cancellation and rejects the old token afterward',async()=>{
 const f=await accepted();let token;await acceptedRead(async()=>{const before=await collectAcceptedAmendmentSources(acceptedSourceExporter,f.business,2);token=before.snapshotToken;await readyCancellation(f);const after=await collectAcceptedAmendmentSources(acceptedSourceExporter,f.business,2);assert.equal(after.snapshotToken,token);assert.deepEqual(after.quotes,before.quotes);assert.deepEqual(after.rows,before.rows);assert.deepEqual(after.bookings,before.bookings);});await assert.rejects(acceptedRead(()=>acceptedSourceExporter.query('SELECT crest_commands.quote_amendment_accepted_source_acceptances($1,$2,NULL,2)',[f.business,token])),e=>e.code==='22023');
});
