 const sample=acceptedSourceCaptures.find(s=>s.capture.rows.agreements.length>=5);assert(sample);const c=structuredClone(sample.capture),audits=new Map(),operations=new Map();for(const record of JSON.parse(c.historyEvidence).records){const row=JSON.parse(record.canonicalEvidence).row;if(record.kind==='operation')operations.set(row.operation_id,row);else audits.set(row.entity_kind+':'+row.entity_id+':'+row.entity_version,row);}
 if(fault==='orphan-version'){c.rows.entitlementVersions.push({...c.rows.entitlementVersions[0],id:randomUUID(),agreement_id:randomUUID()});c.expectedCounts.entitlementVersions=String(c.rows.entitlementVersions.length);}if(fault==='orphan-acceptance'){c.rows.acceptances.push({...c.rows.acceptances[0],id:randomUUID()});c.expectedCounts.acceptances=String(c.rows.acceptances.length);}if(fault==='invalid-active-offer')c.rows.commercialState[0].active_offer_id=c.quotes.revisions.find(r=>r.state==='Accepted').id;
 assert.throws(()=>verifyAcceptedAmendmentSourceGraph({businessId:c.businessId,rows:c.rows,quotes:c.quotes,bookings:c.bookings,audits,operations}),/QUOTE_STORAGE_DATA_INVALID/);
